// GENERATED by tools/build-site.mjs. Do not edit by hand.
window.QOL_PACK = {"manifest":"{\n  \"format_version\": 2,\n  \"header\": {\n    \"name\": \"QoL Add-on\",\n    \"description\": \"Vanilla-feeling quality-of-life features.\",\n    \"uuid\": \"da4dcbf0-26b6-4e7c-8401-2258d880e758\",\n    \"version\": [0, 1, 1],\n    \"min_engine_version\": [1, 26, 60]\n  },\n  \"modules\": [\n    {\n      \"type\": \"script\",\n      \"language\": \"javascript\",\n      \"uuid\": \"8ed2e29a-948f-490b-a54c-c366e78a2c5f\",\n      \"version\": [0, 1, 1],\n      \"entry\": \"scripts/main.js\"\n    }\n  ],\n  \"dependencies\": [\n    { \"module_name\": \"@minecraft/server\", \"version\": \"2.11.0\" },\n    { \"module_name\": \"@minecraft/server-ui\", \"version\": \"2.3.0\" }\n  ]\n}\n","modules":[{"id":"hello","name":"Hello (dev test)","default":true,"description":"Core smoke test. Not shipped in releases.","dev":true,"hasCode":true},{"id":"veinminer","name":"Veinminer","default":true,"description":"Sneak-mine ore veins. Costs real durability.","dev":false,"hasCode":true},{"id":"tree-felling","name":"Tree felling","default":true,"description":"Sneak-chop whole trees. Costs real durability.","dev":false,"hasCode":true},{"id":"auto-fisher","name":"Auto fisher","default":true,"description":"Reels in your catch when a fish bites. You still cast each time.","dev":false,"hasCode":true},{"id":"auto-replant","name":"Auto-replant","default":true,"description":"Harvested crops replant themselves. A hoe harvests and replants the whole field.","dev":false,"hasCode":true},{"id":"tool-warning","name":"Tool warning","default":true,"description":"Warns before a tool breaks.","dev":false,"hasCode":true},{"id":"death-coords","name":"Death coordinates","default":true,"description":"Posts where you died.","dev":false,"hasCode":true},{"id":"sorting","name":"Sorting","default":true,"description":"Sort chests and inventory.","dev":false,"hasCode":true},{"id":"hotbar-swap","name":"Hotbar swap","default":true,"description":"Swap hotbar with an inventory row.","dev":false,"hasCode":true},{"id":"restock","name":"Auto-restock hotbar","default":true,"description":"Refills an emptied hotbar slot from your inventory.","dev":false,"hasCode":true}],"files":{"scripts/core/commands.js":"// Slash commands. PC convenience only; console uses the clock.\nimport {\n  system,\n  Player,\n  CommandPermissionLevel,\n  CustomCommandStatus,\n} from \"@minecraft/server\";\nimport { openSettings } from \"./ui.js\";\n\nexport function initCommands() {\n  system.beforeEvents.startup.subscribe((ev) => {\n    ev.customCommandRegistry.registerCommand(\n      {\n        name: \"qol:settings\",\n        description: \"Open QoL add-on settings\",\n        permissionLevel: CommandPermissionLevel.Any,\n        cheatsRequired: false,\n      },\n      (origin) => {\n        const player = origin.sourceEntity;\n        if (!(player instanceof Player)) {\n          return { status: CustomCommandStatus.Failure, message: \"Players only.\" };\n        }\n        // Callback runs in restricted mode; showWithRetry waits out the open chat.\n        system.run(() => openSettings(player));\n        return { status: CustomCommandStatus.Success };\n      },\n    );\n  });\n}\n","scripts/core/feedback.js":"// Standard response to an instant action: click sound + actionbar text. Never a form.\n\nexport function feedback(player, text, { sound = \"random.click\", pitch = 1.2, volume = 0.4 } = {}) {\n  player.onScreenDisplay.setActionBar(text);\n  player.playSound(sound, { pitch, volume });\n}\n","scripts/core/registry.js":"// Validates module definitions, builds each module's ctx, and isolates errors.\nimport { system } from \"@minecraft/server\";\nimport { defineFields, validate, getSetting, setSetting } from \"./settings.js\";\nimport { claimTrigger } from \"./triggers.js\";\nimport { feedback } from \"./feedback.js\";\n\nconst FIELD_TYPES = [\"toggle\", \"slider\", \"dropdown\"];\n\nfunction makeGuard(moduleId) {\n  return (fn) =>\n    (...args) => {\n      try {\n        return fn(...args);\n      } catch (e) {\n        console.warn(`[qol:${moduleId}] ${e}\\n${e?.stack ?? \"\"}`);\n      }\n    };\n}\n\n/** Returns a list of problems; empty means OK. */\nfunction check(def, meta, seen) {\n  const problems = [];\n  if (!def || typeof def.id !== \"string\") return [\"module has no id\"];\n  if (!meta[def.id]) problems.push(`\"${def.id}\" is not in modules.json`);\n  if (seen.has(def.id)) problems.push(`duplicate module id \"${def.id}\"`);\n  if (typeof def.register !== \"function\") problems.push(\"missing register(ctx)\");\n\n  const keys = new Set();\n  for (const f of def.settings ?? []) {\n    if (!f.key || f.key === \"enabled\") problems.push(`bad setting key \"${f.key}\"`);\n    else if (keys.has(f.key)) problems.push(`duplicate setting \"${f.key}\"`);\n    keys.add(f.key);\n    if (!FIELD_TYPES.includes(f.type)) {\n      problems.push(`setting \"${f.key}\" has unknown type \"${f.type}\"`);\n      continue;\n    }\n    if (f.type === \"slider\" && !(f.min < f.max)) problems.push(`slider \"${f.key}\" needs min < max`);\n    if (f.type === \"dropdown\" && !(f.options?.length > 0)) problems.push(`dropdown \"${f.key}\" has no options`);\n    else if (validate(f, f.default) !== f.default) problems.push(`setting \"${f.key}\" default is out of range`);\n  }\n  for (const m of def.menu ?? []) {\n    if (!m.id || !m.label || typeof m.run !== \"function\") problems.push(`bad menu entry \"${m.id}\"`);\n  }\n  return problems;\n}\n\n/**\n * @param {any[]} modules  module definitions in modules.json order\n * @param {Record<string, { name: string, default: boolean }>} meta\n * @returns {Array<{ def: any, ctx: any }>}\n */\nexport function loadModules(modules, meta) {\n  const seen = new Set();\n  const loaded = [];\n\n  for (const def of modules) {\n    const problems = check(def, meta, seen);\n    if (problems.length) {\n      console.warn(`[qol] skipping module ${def?.id ?? \"?\"}: ${problems.join(\"; \")}`);\n      continue;\n    }\n    seen.add(def.id);\n\n    const id = def.id;\n    defineFields(id, [\n      { key: \"enabled\", type: \"toggle\", label: \"Enabled\", default: meta[id].default },\n      ...(def.settings ?? []),\n    ]);\n\n    const guard = makeGuard(id);\n    const isEnabled = (player) => getSetting(player, id, \"enabled\");\n    const ctx = {\n      id,\n      get: (player, key) => getSetting(player, id, key),\n      set: (player, key, value) => setSetting(player, id, key, value),\n      isEnabled,\n      // `when(player, block?)` narrows when the handler counts as active; for\n      // block triggers that also decides whether core cancels the container open.\n      on: (trigger, fn, when) => {\n        const gate = when ? guard((p, b) => isEnabled(p) && !!when(p, b)) : isEnabled;\n        try {\n          claimTrigger(trigger, id, guard(fn), gate);\n        } catch (e) {\n          console.warn(`[qol:${id}] ${e}`);\n        }\n      },\n      run: (fn) => system.run(guard(fn)),\n      feedback,\n      guard,\n      log: (...args) => console.warn(`[qol:${id}]`, ...args),\n    };\n\n    try {\n      def.register(ctx);\n      loaded.push({ def, ctx });\n    } catch (e) {\n      console.warn(`[qol:${id}] register() failed, module disabled: ${e}\\n${e?.stack ?? \"\"}`);\n    }\n  }\n  return loaded;\n}\n","scripts/core/settings.js":"// Per-player settings over dynamic properties, with an in-memory cache.\n// Keys: qol:<moduleId>:<key>. Values validated against the field on every read.\nimport { world } from \"@minecraft/server\";\n\nconst PREFIX = \"qol\";\nexport const SCHEMA_KEY = `${PREFIX}:core:schema`;\nexport const SCHEMA_VERSION = 1;\n\n/** @type {Map<string, Map<string, any>>} moduleId -> key -> field */\nconst fieldsByModule = new Map();\n/** @type {Map<string, Map<string, any>>} playerId -> propId -> value */\nconst cache = new Map();\n\nexport function defineFields(moduleId, fields) {\n  fieldsByModule.set(moduleId, new Map(fields.map((f) => [f.key, f])));\n}\n\nexport function getFields(moduleId) {\n  return [...(fieldsByModule.get(moduleId)?.values() ?? [])];\n}\n\n/** Coerce a raw value to something valid for the field, else the field default. */\nexport function validate(field, value) {\n  switch (field.type) {\n    case \"toggle\":\n      return typeof value === \"boolean\" ? value : field.default;\n    case \"slider\": {\n      if (typeof value !== \"number\" || !Number.isFinite(value)) return field.default;\n      const step = field.step ?? 1;\n      let v = Math.min(field.max, Math.max(field.min, value));\n      v = field.min + Math.round((v - field.min) / step) * step;\n      return Math.min(field.max, v);\n    }\n    case \"dropdown\":\n      return field.options.some((o) => o.value === value) ? value : field.default;\n    default:\n      return field.default;\n  }\n}\n\nfunction propId(moduleId, key) {\n  return `${PREFIX}:${moduleId}:${key}`;\n}\n\nfunction playerCache(player) {\n  let c = cache.get(player.id);\n  if (!c) cache.set(player.id, (c = new Map()));\n  return c;\n}\n\nfunction getField(moduleId, key) {\n  const field = fieldsByModule.get(moduleId)?.get(key);\n  if (!field) throw new Error(`Unknown setting ${moduleId}:${key}`);\n  return field;\n}\n\nexport function getSetting(player, moduleId, key) {\n  const field = getField(moduleId, key);\n  const id = propId(moduleId, key);\n  const c = playerCache(player);\n  if (c.has(id)) return c.get(id);\n  const value = validate(field, player.getDynamicProperty(id));\n  c.set(id, value);\n  return value;\n}\n\n/** Must be called outside restricted (before-event) mode. */\nexport function setSetting(player, moduleId, key, value) {\n  const field = getField(moduleId, key);\n  const v = validate(field, value);\n  player.setDynamicProperty(propId(moduleId, key), v);\n  playerCache(player).set(propId(moduleId, key), v);\n  return v;\n}\n\nexport function initSettings() {\n  world.afterEvents.playerLeave.subscribe((ev) => cache.delete(ev.playerId));\n  world.afterEvents.playerSpawn.subscribe((ev) => {\n    if (!ev.initialSpawn) return;\n    if (ev.player.getDynamicProperty(SCHEMA_KEY) === undefined) {\n      ev.player.setDynamicProperty(SCHEMA_KEY, SCHEMA_VERSION);\n    }\n  });\n}\n","scripts/core/start.js":"import { initSettings } from \"./settings.js\";\nimport { initTriggers, setMenuOpener } from \"./triggers.js\";\nimport { initCommands } from \"./commands.js\";\nimport { loadModules } from \"./registry.js\";\nimport { openMenu, setLoadedModules } from \"./ui.js\";\n\nexport function start(modules, meta) {\n  initSettings();\n  initTriggers();\n  initCommands();\n  setMenuOpener((player) => openMenu(player));\n  const loaded = loadModules(modules, meta);\n  setLoadedModules(loaded);\n  console.warn(`[qol] loaded ${loaded.length}/${modules.length} modules: ${loaded.map((m) => m.def.id).join(\", \")}`);\n}\n","scripts/core/triggers.js":"// Core owns the trigger-item events so modules never fight over the clock.\n// See docs/CONTRACT.md \"Core triggers\".\nimport { world, system, InputButton, ButtonState } from \"@minecraft/server\";\n\nexport const TRIGGER_ITEMS = {\n  clock: \"minecraft:clock\",\n  compass: \"minecraft:compass\",\n};\n\nexport const TRIGGERS = [\n  \"clock:air:sneak\",\n  \"clock:container:sneak\",\n  \"clock:container\",\n  \"hand:container:sneak\",\n  \"sneak:double\",\n  \"compass:air\",\n];\n\n// Triggers several modules may claim at once. Each claimant gates itself on its\n// own setting (e.g. sorting and hotbar-swap both offer double-tap sneak).\nconst SHARED_TRIGGERS = new Set([\"sneak:double\"]);\n\nconst DOUBLE_SNEAK_WINDOW = 8; // ticks between presses\nconst DOUBLE_SNEAK_COOLDOWN = 40; // ticks (2s)\n\n/** @type {Map<string, Array<{ moduleId: string, fn: Function, isEnabled: (p: any, block?: any) => boolean }>>} */\nconst handlers = new Map();\n/** @type {((player: any) => void) | undefined} */\nlet menuOpener;\n\nexport function claimTrigger(trigger, moduleId, fn, isEnabled) {\n  if (!TRIGGERS.includes(trigger)) throw new Error(`Unknown trigger \"${trigger}\"`);\n  const list = handlers.get(trigger) ?? [];\n  if (list.length && !SHARED_TRIGGERS.has(trigger)) {\n    throw new Error(`Trigger \"${trigger}\" already claimed by ${list[0].moduleId}`);\n  }\n  list.push({ moduleId, fn, isEnabled });\n  handlers.set(trigger, list);\n}\n\nexport function setMenuOpener(fn) {\n  menuOpener = fn;\n}\n\n/** First enabled claimant of an exclusive trigger. */\nfunction active(trigger, player, block) {\n  return handlers.get(trigger)?.find((h) => h.isEnabled(player, block));\n}\n\n/** Every enabled claimant of a shared trigger. */\nfunction allActive(trigger, player) {\n  return (handlers.get(trigger) ?? []).filter((h) => h.isEnabled(player));\n}\n\nexport function initTriggers() {\n  // Tick of the last block interaction per player, so a block click never\n  // also counts as an in-air use.\n  const lastBlockUse = new Map();\n  const lastSneak = new Map();\n  const sneakCooldown = new Map();\n\n  world.beforeEvents.playerInteractWithBlock.subscribe((ev) => {\n    // Fires repeatedly while the button is held: only run the action on the first.\n    const player = ev.player;\n    lastBlockUse.set(player.id, system.currentTick);\n    const emptyHand = !ev.itemStack;\n    if (!emptyHand && ev.itemStack.typeId !== TRIGGER_ITEMS.clock) return;\n    // Empty hand only counts while sneaking; a plain empty-hand click just opens the chest.\n    if (emptyHand && !player.isSneaking) return;\n\n    let hasInventory = false;\n    try {\n      hasInventory = !!ev.block.getComponent(\"minecraft:inventory\");\n    } catch {\n      hasInventory = false;\n    }\n    if (!hasInventory) return;\n\n    const sneaking = player.isSneaking;\n    const trigger = emptyHand\n      ? \"hand:container:sneak\"\n      : sneaking\n        ? \"clock:container:sneak\"\n        : \"clock:container\";\n    const h = active(trigger, player, ev.block);\n    if (!h) return; // nothing claimed / disabled: chest opens normally\n    // Plain clock acts and the chest still opens; sneak + clock / sneak + empty hand\n    // act and never open it.\n    if (sneaking) ev.cancel = true;\n    if (!ev.isFirstEvent) return;\n    const block = ev.block;\n    system.run(() => h.fn(player, block));\n  });\n\n  world.afterEvents.itemUse.subscribe((ev) => {\n    const player = ev.source;\n    if (lastBlockUse.get(player.id) === system.currentTick) return;\n    const id = ev.itemStack?.typeId;\n    if (id === TRIGGER_ITEMS.clock) {\n      if (player.isSneaking) active(\"clock:air:sneak\", player)?.fn(player);\n      else menuOpener?.(player);\n    } else if (id === TRIGGER_ITEMS.compass) {\n      active(\"compass:air\", player)?.fn(player);\n    }\n  });\n\n  world.afterEvents.playerButtonInput.subscribe(\n    (ev) => {\n      const player = ev.player;\n      const hs = allActive(\"sneak:double\", player);\n      if (!hs.length) return;\n      const now = system.currentTick;\n      if ((sneakCooldown.get(player.id) ?? -Infinity) > now) return;\n      const prev = lastSneak.get(player.id);\n      if (prev !== undefined && now - prev <= DOUBLE_SNEAK_WINDOW) {\n        lastSneak.delete(player.id);\n        sneakCooldown.set(player.id, now + DOUBLE_SNEAK_COOLDOWN);\n        for (const h of hs) h.fn(player);\n      } else {\n        lastSneak.set(player.id, now);\n      }\n    },\n    { buttons: [InputButton.Sneak], state: ButtonState.Pressed },\n  );\n\n  world.afterEvents.playerLeave.subscribe((ev) => {\n    lastBlockUse.delete(ev.playerId);\n    lastSneak.delete(ev.playerId);\n    sneakCooldown.delete(ev.playerId);\n  });\n}\n","scripts/core/ui.js":"// Clock menu + settings forms. Forms are only for the menu and settings,\n// never for instant actions.\nimport { system } from \"@minecraft/server\";\nimport { ActionFormData, ModalFormData, FormCancelationReason } from \"@minecraft/server-ui\";\nimport { getFields, getSetting, setSetting } from \"./settings.js\";\n\nconst sleep = (ticks) => new Promise((resolve) => system.runTimeout(() => resolve(undefined), ticks));\n\n/**\n * Show a form, retrying while the player is busy (chat open, other screen).\n * Resolves undefined if it never got through or the player left.\n */\nexport async function showWithRetry(form, player, { tries = 10, interval = 10 } = {}) {\n  for (let i = 0; i < tries; i++) {\n    if (!player.isValid) return undefined;\n    const res = await form.show(player);\n    if (!(res.canceled && res.cancelationReason === FormCancelationReason.UserBusy)) return res;\n    await sleep(interval);\n  }\n  return undefined;\n}\n\n/** @type {Array<{ def: any, ctx: any }>} */\nlet loaded = [];\n\nexport function setLoadedModules(list) {\n  loaded = list;\n}\n\nexport async function openMenu(player) {\n  const entries = [];\n  for (const { def, ctx } of loaded) {\n    if (!ctx.isEnabled(player)) continue;\n    for (const entry of def.menu ?? []) entries.push({ entry, ctx });\n  }\n\n  const form = new ActionFormData().title(\"QoL\");\n  for (const { entry } of entries) form.button(entry.label);\n  form.button(\"Settings\");\n\n  const res = await showWithRetry(form, player);\n  if (!res || res.canceled || res.selection === undefined) return;\n  if (res.selection === entries.length) return openSettings(player);\n  const { entry, ctx } = entries[res.selection];\n  ctx.guard(() => entry.run(player, ctx))();\n}\n\nexport async function openSettings(player) {\n  while (player.isValid) {\n    const form = new ActionFormData().title(\"QoL Settings\");\n    for (const { def, ctx } of loaded) {\n      form.button(`${def.name}  ${ctx.isEnabled(player) ? \"§aON\" : \"§7OFF\"}`);\n    }\n    const res = await showWithRetry(form, player);\n    if (!res || res.canceled || res.selection === undefined) return;\n    await openModuleSettings(player, loaded[res.selection]);\n  }\n}\n\nasync function openModuleSettings(player, { def }) {\n  const fields = getFields(def.id);\n  const form = new ModalFormData().title(def.name).submitButton(\"Save\");\n  for (const f of fields) {\n    const current = getSetting(player, def.id, f.key);\n    if (f.type === \"toggle\") {\n      form.toggle(f.label, { defaultValue: current, tooltip: f.tooltip });\n    } else if (f.type === \"slider\") {\n      form.slider(f.label, f.min, f.max, { valueStep: f.step ?? 1, defaultValue: current, tooltip: f.tooltip });\n    } else if (f.type === \"dropdown\") {\n      const idx = Math.max(0, f.options.findIndex((o) => o.value === current));\n      form.dropdown(f.label, f.options.map((o) => o.label), { defaultValueIndex: idx, tooltip: f.tooltip });\n    }\n  }\n\n  const res = await showWithRetry(form, player);\n  if (!res || res.canceled || !res.formValues) return; // back to the list\n  fields.forEach((f, i) => {\n    let value = res.formValues[i];\n    if (f.type === \"dropdown\") value = f.options[/** @type {number} */ (value)]?.value;\n    setSetting(player, def.id, f.key, value);\n  });\n}\n","scripts/lib/bulk-break.js":"// Shared by veinminer + tree-felling: flood fill through connected same-key\n// blocks, vanilla-accurate drops/XP via the loot table, and real durability\n// cost. See docs/MODULES.md and docs/CONTRACT.md \"lib/\".\nimport { world, GameMode } from \"@minecraft/server\";\nimport { getUnbreakingLevel, remainingDurability, damageItem } from \"./items.js\";\n\nconst NEIGHBORS = [];\nfor (let x = -1; x <= 1; x++)\n  for (let y = -1; y <= 1; y++)\n    for (let z = -1; z <= 1; z++) if (x || y || z) NEIGHBORS.push({ x, y, z });\n\nfunction posKey(loc) {\n  return `${loc.x},${loc.y},${loc.z}`;\n}\n\n/**\n * Flood-fills out from `origin` (already broken by the player's own hit)\n * through same-key neighbors, breaking up to `cap - 1` more blocks.\n *\n * @param {object} opts\n * @param {import(\"@minecraft/server\").Player} opts.player\n * @param {import(\"@minecraft/server\").Block} opts.origin  the now-air block the player just broke\n * @param {string} opts.originKey  `key()` applied to the block's type *before* it was broken\n * @param {(typeId: string) => string} opts.key  groups block types that count as the same vein/tree\n * @param {number} opts.cap  vein size cap, including the origin block\n * @param {boolean} opts.protectTool  stop at 1 durability left instead of letting the tool break\n * @param {(block: import(\"@minecraft/server\").Block) => number} [opts.xp]  XP for one extra block (0/omit for none)\n * @returns {{ broken: number, toolBroke: boolean }}\n */\nexport function bulkBreak({ player, origin, originKey, key, cap, protectTool, xp }) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  let tool = container?.getItem(player.selectedSlotIndex);\n  if (!container || !tool) return { broken: 0, toolBroke: false };\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  const unbreaking = getUnbreakingLevel(tool);\n  const dimension = origin.dimension;\n  const lootManager = world.getLootTableManager();\n\n  const seen = new Set([posKey(origin.location)]);\n  const queue = [origin.location];\n  let broken = 0;\n  let toolBroke = false;\n\n  outer: while (queue.length > 0 && broken < cap - 1) {\n    const loc = queue.shift();\n    for (const d of NEIGHBORS) {\n      const next = { x: loc.x + d.x, y: loc.y + d.y, z: loc.z + d.z };\n      const k = posKey(next);\n      if (seen.has(k)) continue;\n      seen.add(k);\n\n      const block = dimension.getBlock(next);\n      if (!block || key(block.permutation.type.id) !== originKey) continue;\n\n      if (!creative && protectTool && remainingDurability(tool) <= 1) break outer;\n\n      const loot = lootManager.generateLootFromBlockPermutation(block.permutation, tool);\n      if (loot === undefined) continue; // tool tier can't harvest this one: skip it\n\n      block.setType(\"minecraft:air\");\n      for (const stack of loot) dimension.spawnItem(stack, block.location);\n      if (!creative) {\n        const amount = xp?.(block) ?? 0;\n        if (amount > 0) dimension.spawnXp(block.location, amount);\n      }\n      broken++;\n\n      if (!creative) {\n        tool = damageItem(tool, unbreaking);\n        if (!tool) {\n          toolBroke = true;\n          break outer;\n        }\n      }\n\n      queue.push(next);\n      if (broken >= cap - 1) break outer;\n    }\n  }\n\n  if (!creative) {\n    container.setItem(player.selectedSlotIndex, tool); // tool undefined when broken: clears the slot\n    if (toolBroke) player.playSound(\"random.break\");\n  }\n\n  return { broken, toolBroke };\n}\n","scripts/lib/containers.js":"// Container helpers for sorting: storage detection and merge + alphabetical sort.\n\nconst STORAGE = /(^|_)(chest|barrel|shulker_box)$/;\n\n/** True for player-style storage blocks (chests, barrels, shulker boxes), not furnaces/hoppers/etc. */\nexport function isStorageBlock(block) {\n  return STORAGE.test(block.typeId.replace(\"minecraft:\", \"\"));\n}\n\nexport function getBlockContainer(block) {\n  return block.getComponent(\"minecraft:inventory\")?.container;\n}\n\nexport function getPlayerContainer(player) {\n  return player.getComponent(\"minecraft:inventory\")?.container;\n}\n\n/** Slot range `[from, to)` of a player's inventory: hotbar is 0-8, main inventory 9-35. */\nexport function playerRange(includeHotbar) {\n  return [includeHotbar ? 0 : 9, 36];\n}\n\n/**\n * Merges partial stacks in slots `[from, to)` of `container`, then orders them\n * alphabetically by item id (bigger stacks first), packing empty slots to the end.\n */\nexport function sortRange(container, from = 0, to = container.size) {\n  const merged = [];\n  for (let i = from; i < to; i++) {\n    const item = container.getItem(i);\n    if (!item) continue;\n    let left = item.amount;\n    for (const stack of merged) {\n      if (left === 0) break;\n      if (stack.amount >= stack.maxAmount || !stack.isStackableWith(item)) continue;\n      const moved = Math.min(stack.maxAmount - stack.amount, left);\n      stack.amount += moved;\n      left -= moved;\n    }\n    if (left > 0) {\n      const rest = item.clone();\n      rest.amount = left;\n      merged.push(rest);\n    }\n  }\n\n  merged.sort((a, b) => {\n    const byId = a.typeId < b.typeId ? -1 : a.typeId > b.typeId ? 1 : 0;\n    return byId || b.amount - a.amount;\n  });\n\n  for (let i = from; i < to; i++) container.setItem(i, merged[i - from]);\n}\n","scripts/lib/items.js":"// Held-item helpers: read the item in a player's selected slot and spend\n// durability the vanilla way, via getDamageChance (no hand-rolled Unbreaking\n// odds). See docs/VERIFY.md \"Durability + Unbreaking\".\n\nexport function getUnbreakingLevel(item) {\n  return item.getComponent(\"minecraft:enchantable\")?.getEnchantment(\"unbreaking\")?.level ?? 0;\n}\n\n/** Durability points left before the tool breaks, or Infinity if unbreakable/no durability component. */\nexport function remainingDurability(item) {\n  const durability = item.getComponent(\"minecraft:durability\");\n  if (!durability || durability.unbreakable) return Infinity;\n  return durability.maxDurability - durability.damage;\n}\n\n/**\n * Spends one vanilla \"use\" of durability on `item`, following the odds from\n * getDamageChance(unbreakingLevel). Mutates and returns the item, or\n * returns undefined if this use broke it.\n */\nexport function damageItem(item, unbreakingLevel) {\n  const durability = item.getComponent(\"minecraft:durability\");\n  if (!durability || durability.unbreakable) return item;\n  // getDamageChance is a percentage: 100 with no Unbreaking, 25 at Unbreaking III.\n  if (Math.random() * 100 >= durability.getDamageChance(unbreakingLevel)) return item;\n  durability.damage += 1;\n  return durability.damage >= durability.maxDurability ? undefined : item;\n}\n","scripts/main.js":"import { start } from \"./core/start.js\";\nimport modules, { moduleMeta } from \"./modules/index.js\";\n\nstart(modules, moduleMeta);\n","scripts/modules/auto-fisher/index.js":"// Cast as usual; when a fish bites, the catch is reeled in for you: vanilla\n// fishing loot (rod enchantments apply), XP, and one durability point per\n// catch. You still cast every time. See docs/MODULES.md#auto-fisher.\nimport { world, system } from \"@minecraft/server\";\nimport { damageItem, getUnbreakingLevel } from \"../../lib/items.js\";\n\nconst SETTLE_TICKS = 20; // ignore the splash when the hook lands\nconst BITE_VELOCITY = -0.1; // vertical speed of the bite dip (idle bobbing stays above this)\nconst GIVE_UP_TICKS = 20 * 60 * 2; // hook left unattended for 2 minutes\n\nexport default {\n  id: \"auto-fisher\",\n  name: \"Auto fisher\",\n\n  settings: [],\n\n  register(ctx) {\n    world.afterEvents.entitySpawn.subscribe(\n      ctx.guard((ev) => {\n        const hook = ev.entity;\n        if (hook.typeId !== \"minecraft:fishing_hook\") return;\n        const player = hook.getComponent(\"minecraft:projectile\")?.owner;\n        if (!player || player.typeId !== \"minecraft:player\" || !ctx.isEnabled(player)) return;\n\n        let ticks = 0;\n        let inWater = 0;\n        const id = system.runInterval(\n          ctx.guard(() => {\n            ticks++;\n            if (!hook.isValid || !player.isValid || ticks > GIVE_UP_TICKS) return system.clearRun(id);\n            if (!hook.isInWater) return;\n            inWater++;\n            if (inWater > SETTLE_TICKS && hook.getVelocity().y < BITE_VELOCITY) {\n              system.clearRun(id);\n              reelIn(player, hook, ctx);\n            }\n          }),\n          1,\n        );\n      }),\n    );\n  },\n};\n\nfunction reelIn(player, hook, ctx) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  const slot = player.selectedSlotIndex;\n  const rod = container?.getItem(slot);\n  if (rod?.typeId !== \"minecraft:fishing_rod\") return; // not holding the rod: leave the hook alone\n\n  const table = world.getLootTableManager().getLootTable(\"gameplay/fishing\");\n  const loot = table && world.getLootTableManager().generateLootFromTable(table, rod);\n  if (!loot) return;\n\n  const spot = hook.location;\n  hook.remove();\n  for (const stack of loot) {\n    const left = container.addItem(stack);\n    if (left) player.dimension.spawnItem(left, player.location);\n  }\n  player.dimension.spawnXp(player.location, 1 + Math.floor(Math.random() * 6));\n  player.dimension.playSound?.(\"random.splash\", spot);\n\n  if (player.getGameMode() !== \"Creative\") {\n    container.setItem(slot, damageItem(rod, getUnbreakingLevel(rod)));\n  }\n  ctx.feedback(player, `Caught ${loot.map((s) => `${s.amount} ${s.typeId.replace(\"minecraft:\", \"\").replace(/_/g, \" \")}`).join(\", \") || \"nothing\"}`);\n}\n","scripts/modules/auto-replant/index.js":"// Harvesting a mature crop replants it with any tool (or bare hand), paying\n// with one seed/item from the drops. No seed in the drops means no replant.\n// With a hoe, the whole connected field of that crop is harvested and\n// replanted, costing real hoe durability per extra crop.\n// See docs/MODULES.md#auto-replant.\nimport { world, system, BlockPermutation, GameMode } from \"@minecraft/server\";\nimport { getUnbreakingLevel, remainingDurability, damageItem } from \"../../lib/items.js\";\n\nconst MAX_TRIES = 8; // ticks to wait for the drops to appear\n\n// block id -> growth state name, mature value, and the dropped item that replants it.\nconst CROPS = {\n  \"minecraft:wheat\": { state: \"growth\", mature: 7, seed: \"minecraft:wheat_seeds\" },\n  \"minecraft:carrots\": { state: \"growth\", mature: 7, seed: \"minecraft:carrot\" },\n  \"minecraft:potatoes\": { state: \"growth\", mature: 7, seed: \"minecraft:potato\" },\n  \"minecraft:beetroot\": { state: \"growth\", mature: 7, seed: \"minecraft:beetroot_seeds\" },\n  \"minecraft:nether_wart\": { state: \"age\", mature: 3, seed: \"minecraft:nether_wart\" },\n};\n\n// Fields can step up/down a block (terraces), so all 26 neighbors count.\nconst NEIGHBORS = [];\nfor (let x = -1; x <= 1; x++)\n  for (let y = -1; y <= 1; y++)\n    for (let z = -1; z <= 1; z++) if (x || y || z) NEIGHBORS.push({ x, y, z });\n\nconst posKey = (l) => `${l.x},${l.y},${l.z}`;\n\n/** Removes one `seedId` from the drops near `center`. Returns true if one was found. */\nfunction takeSeed(dimension, center, seedId) {\n  const drops = dimension.getEntities({ type: \"minecraft:item\", location: center, maxDistance: 2 });\n  for (const drop of drops) {\n    const stack = drop.getComponent(\"minecraft:item\")?.itemStack;\n    if (stack?.typeId !== seedId) continue;\n    if (stack.amount > 1) {\n      const rest = stack.clone();\n      rest.amount = stack.amount - 1;\n      dimension.spawnItem(rest, drop.location);\n    }\n    drop.remove();\n    return true;\n  }\n  return false;\n}\n\n/** Replants the crop the player broke by hand, using a seed from its drops. */\nfunction replantOrigin(ctx, dimension, loc, cropId, crop) {\n  // Drops spawn a tick or two after the break event, so keep looking briefly.\n  const center = { x: loc.x + 0.5, y: loc.y + 0.5, z: loc.z + 0.5 };\n  let tries = 0;\n  const attempt = () => {\n    try {\n      const block = dimension.getBlock(loc);\n      if (!block?.isAir) return;\n      if (takeSeed(dimension, center, crop.seed)) {\n        block.setPermutation(BlockPermutation.resolve(cropId, { [crop.state]: 0 }));\n      } else if (++tries < MAX_TRIES) {\n        system.run(attempt);\n      }\n    } catch (e) {\n      ctx.log(e);\n    }\n  };\n  system.run(attempt);\n}\n\n/**\n * Walks the connected field of `cropId` (through crops of any age) and\n * harvests + replants every mature one, up to `cap`. Each harvest uses the\n * vanilla loot table with the hoe (Fortune applies), keeps one seed back to\n * replant, and spends one use of hoe durability. Stops at 1 durability left.\n * @returns {number} crops harvested (not counting the origin)\n */\nfunction harvestField(player, dimension, originLoc, cropId, crop, cap) {\n  const container = player.getComponent(\"minecraft:inventory\")?.container;\n  let tool = container?.getItem(player.selectedSlotIndex);\n  if (!container || !tool?.typeId.endsWith(\"_hoe\")) return 0;\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  const unbreaking = getUnbreakingLevel(tool);\n  const lootManager = world.getLootTableManager();\n\n  const seen = new Set([posKey(originLoc)]);\n  const queue = [originLoc];\n  let harvested = 0;\n\n  outer: while (queue.length > 0) {\n    const loc = queue.shift();\n    for (const d of NEIGHBORS) {\n      const next = { x: loc.x + d.x, y: loc.y + d.y, z: loc.z + d.z };\n      const k = posKey(next);\n      if (seen.has(k)) continue;\n      seen.add(k);\n\n      const block = dimension.getBlock(next);\n      if (!block || block.typeId !== cropId) continue;\n      queue.push(next); // young crops still connect the field\n\n      const perm = block.permutation;\n      if (perm.getState(crop.state) !== crop.mature) continue;\n      if (!creative && remainingDurability(tool) <= 1) break outer;\n\n      const loot = lootManager.generateLootFromBlockPermutation(perm, tool);\n      if (loot === undefined) continue;\n\n      // Keep one seed back for the replant; if there's none, the crop is just harvested.\n      let replanted = false;\n      for (const stack of loot) {\n        if (!replanted && stack.typeId === crop.seed) {\n          replanted = true;\n          if (stack.amount <= 1) continue;\n          stack.amount -= 1;\n        }\n        dimension.spawnItem(stack, { x: next.x + 0.5, y: next.y + 0.5, z: next.z + 0.5 });\n      }\n      block.setPermutation(\n        replanted ? BlockPermutation.resolve(cropId, { [crop.state]: 0 }) : BlockPermutation.resolve(\"minecraft:air\"),\n      );\n      harvested++;\n\n      if (!creative) tool = damageItem(tool, unbreaking); // protected above, never breaks\n      if (harvested >= cap - 1) break outer;\n    }\n  }\n\n  if (!creative && harvested > 0) container.setItem(player.selectedSlotIndex, tool);\n  return harvested;\n}\n\nexport default {\n  id: \"auto-replant\",\n  name: \"Auto-replant\",\n\n  settings: [\n    { key: \"field\", type: \"toggle\", label: \"Hoe harvests the whole field\", default: true },\n    { key: \"fieldSneak\", type: \"toggle\", label: \"Whole field only while sneaking\", default: false },\n    { key: \"cap\", type: \"slider\", label: \"Max crops per field\", default: 128, min: 16, max: 256, step: 16 },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      const player = ev.player;\n      if (!ctx.isEnabled(player)) return;\n      const perm = ev.brokenBlockPermutation;\n      const cropId = perm.type.id;\n      const crop = CROPS[cropId];\n      if (!crop || perm.getState(crop.state) !== crop.mature) return;\n\n      const { dimension } = ev;\n      const loc = ev.block.location;\n      replantOrigin(ctx, dimension, loc, cropId, crop);\n\n      const hoe = ev.itemStackBeforeBreak?.typeId.endsWith(\"_hoe\");\n      if (!hoe || !ctx.get(player, \"field\")) return;\n      if (ctx.get(player, \"fieldSneak\") && !player.isSneaking) return;\n\n      const cap = ctx.get(player, \"cap\");\n      ctx.run(() => {\n        const n = harvestField(player, dimension, loc, cropId, crop, cap);\n        if (n > 0) ctx.feedback(player, `Harvested ${n + 1} crops`);\n      });\n    });\n  },\n};\n","scripts/modules/death-coords/index.js":"// Posts where you died (coordinates + dimension) to your own chat.\n// See docs/MODULES.md#death-coords.\nimport { world } from \"@minecraft/server\";\n\nconst DIMENSIONS = {\n  \"minecraft:overworld\": \"Overworld\",\n  \"minecraft:nether\": \"Nether\",\n  \"minecraft:the_end\": \"End\",\n};\n\nexport default {\n  id: \"death-coords\",\n  name: \"Death coordinates\",\n\n  settings: [],\n\n  register(ctx) {\n    world.afterEvents.entityDie.subscribe(\n      ctx.guard((ev) => {\n        const player = ev.deadEntity;\n        if (player.typeId !== \"minecraft:player\" || !ctx.isEnabled(player)) return;\n        const { x, y, z } = player.location;\n        const dim = DIMENSIONS[player.dimension.id] ?? player.dimension.id;\n        player.sendMessage(`§c[QoL] You died at ${Math.floor(x)} ${Math.floor(y)} ${Math.floor(z)} (${dim})`);\n      }),\n    );\n  },\n};\n","scripts/modules/hello/index.js":"// Dev-only smoke test for core: every trigger, every field type, a menu entry,\n// and a join message (proves the pack runs on a Realm). Not shipped in releases.\nimport { world, system } from \"@minecraft/server\";\nimport { getSetting, setSetting } from \"../../core/settings.js\";\n\nexport default {\n  id: \"hello\",\n  name: \"Hello (dev test)\",\n\n  settings: [\n    { key: \"greet\", type: \"toggle\", label: \"Greet on join\", default: true },\n    { key: \"pitch\", type: \"slider\", label: \"Click pitch x10\", default: 12, min: 5, max: 20, step: 1 },\n    {\n      key: \"word\",\n      type: \"dropdown\",\n      label: \"Greeting word\",\n      default: \"hello\",\n      options: [\n        { value: \"hello\", label: \"Hello\" },\n        { value: \"howdy\", label: \"Howdy\" },\n        { value: \"yo\", label: \"Yo\" },\n      ],\n    },\n  ],\n\n  menu: [\n    {\n      id: \"ping\",\n      label: \"Ping\",\n      run(player, ctx) {\n        ctx.feedback(player, \"§aPong from the menu\");\n      },\n    },\n  ],\n\n  register(ctx) {\n    // Bridge round-trip test: `npm run mc -- cmd \"scriptevent qol:ping hi\"` then wait for \"pong\".\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:ping\") return;\n      const text = `[qol] pong ${ev.message}`.trim();\n      world.sendMessage(text);\n      console.warn(text);\n    });\n\n    // Dev probe: `scriptevent qol:item` prints the first player's held-item durability numbers.\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:item\") return;\n      const p = world.getAllPlayers()[0];\n      const item = p?.getComponent(\"minecraft:inventory\")?.container?.getItem(p.selectedSlotIndex);\n      const d = item?.getComponent(\"minecraft:durability\");\n      const text = d\n        ? `[qol] ${item.typeId} damage=${d.damage} max=${d.maxDurability} chance(0)=${d.getDamageChance(0)} chance(3)=${d.getDamageChance(3)}`\n        : `[qol] no durability item in hand (${item?.typeId})`;\n      world.sendMessage(text);\n      console.warn(text);\n    });\n\n    // Dev probe: `scriptevent qol:set <module> <key> <value>` writes the first player's setting (true/false/number/string).\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:set\") return;\n      const p = world.getAllPlayers()[0];\n      const [moduleId, key, raw] = ev.message.split(\" \");\n      const value = raw === \"true\" ? true : raw === \"false\" ? false : Number.isNaN(Number(raw)) ? raw : Number(raw);\n      try {\n        world.sendMessage(`[qol] set ${moduleId}.${key} -> ${setSetting(p, moduleId, key, value)}`);\n      } catch (e) {\n        world.sendMessage(`[qol] set failed: ${e}`);\n      }\n    });\n\n    // Dev probe: `scriptevent qol:dump self|<x> <y> <z>` prints non-empty slots as slot:item*count.\n    system.afterEvents.scriptEventReceive.subscribe((ev) => {\n      if (ev.id !== \"qol:dump\") return;\n      const p = world.getAllPlayers()[0];\n      const [x, y, z] = ev.message.split(\" \").map(Number);\n      const container =\n        ev.message.trim() === \"self\"\n          ? p?.getComponent(\"minecraft:inventory\")?.container\n          : p?.dimension.getBlock({ x, y, z })?.getComponent(\"minecraft:inventory\")?.container;\n      if (!container) return world.sendMessage(\"[qol] dump: no container\");\n      const parts = [];\n      for (let i = 0; i < container.size; i++) {\n        const item = container.getItem(i);\n        if (item) parts.push(`${i}:${item.typeId.replace(\"minecraft:\", \"\")}*${item.amount}`);\n      }\n      world.sendMessage(`[qol] dump size=${container.size} ${parts.join(\" \")}`);\n    });\n\n    world.afterEvents.playerSpawn.subscribe((ev) => {\n      if (!ev.initialSpawn) return;\n      const p = ev.player;\n      try {\n        if (!ctx.isEnabled(p) || !ctx.get(p, \"greet\")) return;\n        const word = ctx.get(p, \"word\");\n        p.sendMessage(`§e[QoL] ${word}, ${p.name}! Add-on is running. Clock = menu, sneak+clock = test.`);\n      } catch (e) {\n        ctx.log(e);\n      }\n    });\n  },\n};\n","scripts/modules/hotbar-swap/index.js":"// Rotates the hotbar through the enabled inventory rows:\n// hotbar <- row A <- row B <- ... <- old hotbar. Repeated use cycles back to\n// where you started. Triggers: compass in air, or double-tap sneak (opt-in) so\n// it still works with the compass in your offhand. The clock menu can move the\n// compass in/out of the offhand slot. See docs/MODULES.md#hotbar-swap.\nimport { EntityComponentTypes, EquipmentSlot } from \"@minecraft/server\";\nimport { getPlayerContainer } from \"../../lib/containers.js\";\n\nconst COMPASS = \"minecraft:compass\";\n\n// Main inventory is slots 9-35. Row 1 is the one right above the hotbar.\nconst ROWS = [\n  { key: \"row1\", label: \"Use row 1 (just above hotbar)\", start: 27 },\n  { key: \"row2\", label: \"Use row 2 (middle)\", start: 18 },\n  { key: \"row3\", label: \"Use row 3 (top)\", start: 9 },\n];\n\n/** @param {import(\"@minecraft/server\").Player} player */\nfunction getEquippable(player) {\n  return /** @type {import(\"@minecraft/server\").EntityEquippableComponent | undefined} */ (\n    player.getComponent(EntityComponentTypes.Equippable)\n  );\n}\n\n/**\n * Compass in inventory -> offhand (whatever was in the offhand takes its slot).\n * Compass already in offhand -> back into the inventory.\n */\nfunction toggleOffhandCompass(player, ctx) {\n  const container = getPlayerContainer(player);\n  const equip = getEquippable(player);\n  if (!container || !equip) return;\n  const offhand = equip.getEquipment(EquipmentSlot.Offhand);\n\n  if (offhand?.typeId === COMPASS) {\n    const leftover = container.addItem(offhand);\n    if (leftover) {\n      ctx.feedback(player, \"Inventory full\");\n      return;\n    }\n    equip.setEquipment(EquipmentSlot.Offhand, undefined);\n    ctx.feedback(player, \"Compass back in inventory\");\n    return;\n  }\n\n  let slot = -1;\n  for (let i = 0; i < container.size; i++) {\n    if (container.getItem(i)?.typeId === COMPASS) {\n      slot = i;\n      break;\n    }\n  }\n  if (slot < 0) {\n    ctx.feedback(player, \"No compass in inventory\");\n    return;\n  }\n\n  const compass = container.getItem(slot);\n  if (!equip.setEquipment(EquipmentSlot.Offhand, compass)) {\n    ctx.feedback(player, \"Couldn't move the compass\");\n    return;\n  }\n  container.setItem(slot, offhand); // old offhand item (or nothing) takes the compass's spot\n  ctx.feedback(player, \"Compass in offhand\");\n}\n\nexport default {\n  id: \"hotbar-swap\",\n  name: \"Hotbar swap\",\n\n  settings: [\n    ...ROWS.map((r) => ({ key: r.key, type: \"toggle\", label: r.label, default: true })),\n    { key: \"doubleTapSneak\", type: \"toggle\", label: \"Double-tap sneak to swap hotbar\", default: false },\n  ],\n\n  menu: [\n    {\n      id: \"compass-offhand\",\n      label: \"Compass to/from offhand\",\n      run(player, ctx) {\n        toggleOffhandCompass(player, ctx);\n      },\n    },\n  ],\n\n  register(ctx) {\n    const swap = (player, keepHeld) => {\n      const container = getPlayerContainer(player);\n      if (!container) return;\n\n      const starts = [0, ...ROWS.filter((r) => ctx.get(player, r.key)).map((r) => r.start)];\n      if (starts.length < 2) {\n        ctx.feedback(player, \"No rows enabled\");\n        return;\n      }\n\n      // Compass use keeps the held column put so the compass stays in your hand.\n      const held = keepHeld ? player.selectedSlotIndex : -1;\n      const snapshot = starts.map((start) => {\n        const row = [];\n        for (let i = 0; i < 9; i++) row.push(container.getItem(start + i));\n        return row;\n      });\n      starts.forEach((start, j) => {\n        const incoming = snapshot[(j + 1) % starts.length];\n        for (let i = 0; i < 9; i++) {\n          if (i !== held) container.setItem(start + i, incoming[i]);\n        }\n      });\n\n      ctx.feedback(player, \"Hotbar swapped\");\n    };\n\n    ctx.on(\"compass:air\", (player) => swap(player, true));\n    ctx.on(\"sneak:double\", (player) => {\n      if (ctx.get(player, \"doubleTapSneak\")) swap(player, false);\n    });\n  },\n};\n","scripts/modules/index.js":"// GENERATED by tools/gen-index.mjs from modules.json. Do not edit by hand.\nimport hello from \"./hello/index.js\";\nimport veinminer from \"./veinminer/index.js\";\nimport treeFelling from \"./tree-felling/index.js\";\nimport autoFisher from \"./auto-fisher/index.js\";\nimport autoReplant from \"./auto-replant/index.js\";\nimport toolWarning from \"./tool-warning/index.js\";\nimport deathCoords from \"./death-coords/index.js\";\nimport sorting from \"./sorting/index.js\";\nimport hotbarSwap from \"./hotbar-swap/index.js\";\nimport restock from \"./restock/index.js\";\n\nexport const moduleMeta = {\n  \"hello\": {\n    \"name\": \"Hello (dev test)\",\n    \"default\": true\n  },\n  \"veinminer\": {\n    \"name\": \"Veinminer\",\n    \"default\": true\n  },\n  \"tree-felling\": {\n    \"name\": \"Tree felling\",\n    \"default\": true\n  },\n  \"auto-fisher\": {\n    \"name\": \"Auto fisher\",\n    \"default\": true\n  },\n  \"auto-replant\": {\n    \"name\": \"Auto-replant\",\n    \"default\": true\n  },\n  \"tool-warning\": {\n    \"name\": \"Tool warning\",\n    \"default\": true\n  },\n  \"death-coords\": {\n    \"name\": \"Death coordinates\",\n    \"default\": true\n  },\n  \"sorting\": {\n    \"name\": \"Sorting\",\n    \"default\": true\n  },\n  \"hotbar-swap\": {\n    \"name\": \"Hotbar swap\",\n    \"default\": true\n  },\n  \"restock\": {\n    \"name\": \"Auto-restock hotbar\",\n    \"default\": true\n  }\n};\n\nexport default [hello, veinminer, treeFelling, autoFisher, autoReplant, toolWarning, deathCoords, sorting, hotbarSwap, restock];\n","scripts/modules/restock/index.js":"// Refills an emptied hotbar slot from the rest of your inventory: a broken\n// tool or a used-up block stack gets swapped for a matching one you're\n// still carrying. See docs/MODULES.md#restock.\nimport { world, PlayerInventoryType } from \"@minecraft/server\";\nimport { getPlayerContainer, playerRange } from \"../../lib/containers.js\";\n\nexport default {\n  id: \"restock\",\n  name: \"Auto-restock hotbar\",\n\n  settings: [],\n\n  register(ctx) {\n    world.afterEvents.playerInventoryItemChange.subscribe(\n      (ev) => {\n        if (!ctx.isEnabled(ev.player)) return;\n        if (ev.inventoryType !== PlayerInventoryType.Hotbar) return;\n        if (ev.itemStack || !ev.beforeItemStack) return; // slot still has something, or was already empty\n\n        const typeId = ev.beforeItemStack.typeId;\n        ctx.run(() => {\n          const container = getPlayerContainer(ev.player);\n          if (!container || container.getItem(ev.slot)) return; // something already filled it since\n\n          const [from, to] = playerRange(false);\n          for (let i = from; i < to; i++) {\n            if (container.getItem(i)?.typeId === typeId) {\n              container.moveItem(i, ev.slot, container);\n              return;\n            }\n          }\n        });\n      },\n      { allowedSlots: [0, 1, 2, 3, 4, 5, 6, 7, 8] },\n    );\n  },\n};\n","scripts/modules/sorting/index.js":"// Instant sorting: sneak + clock in air sorts your inventory, sneak + clock on a\n// chest (or sneak + empty hand on a chest) sorts it, optional double-tap sneak. No forms. See docs/MODULES.md#sorting.\nimport { getBlockContainer, getPlayerContainer, isStorageBlock, playerRange, sortRange } from \"../../lib/containers.js\";\n\nexport default {\n  id: \"sorting\",\n  name: \"Sorting\",\n\n  settings: [\n    { key: \"includeHotbar\", type: \"toggle\", label: \"Include hotbar when sorting inventory\", default: false },\n    { key: \"doubleTapSneak\", type: \"toggle\", label: \"Double-tap sneak to sort inventory\", default: false },\n    { key: \"emptyHand\", type: \"toggle\", label: \"Sneak + empty hand sorts containers\", default: true },\n  ],\n\n  register(ctx) {\n    const sortInventory = (player) => {\n      const container = getPlayerContainer(player);\n      if (!container) return;\n      const [from, to] = playerRange(ctx.get(player, \"includeHotbar\"));\n      sortRange(container, from, to);\n      ctx.feedback(player, \"Inventory sorted\");\n    };\n\n    ctx.on(\"clock:air:sneak\", sortInventory);\n\n    ctx.on(\"sneak:double\", (player) => {\n      if (ctx.get(player, \"doubleTapSneak\")) sortInventory(player);\n    });\n\n    const sortContainer = (player, block) => {\n      const container = getBlockContainer(block);\n      if (!container || !isStorageBlock(block)) {\n        ctx.feedback(player, \"Can't sort that\");\n        return;\n      }\n      sortRange(container);\n      ctx.feedback(player, \"Container sorted\");\n    };\n\n    ctx.on(\"clock:container:sneak\", sortContainer);\n    ctx.on(\"hand:container:sneak\", sortContainer, (player, block) => ctx.get(player, \"emptyHand\") && isStorageBlock(block));\n  },\n};\n","scripts/modules/tool-warning/index.js":"// Sound + actionbar warning once when the held tool drops to the threshold.\n// See docs/MODULES.md#tool-warning.\nimport { world, system } from \"@minecraft/server\";\n\nconst CHECK_TICKS = 10;\n\nexport default {\n  id: \"tool-warning\",\n  name: \"Tool warning\",\n\n  settings: [\n    { key: \"percent\", type: \"slider\", label: \"Warn at % durability left\", default: 10, min: 5, max: 30, step: 5 },\n  ],\n\n  register(ctx) {\n    // playerId -> \"<typeId>:<slot>\" of the item already warned about\n    const warned = new Map();\n\n    system.runInterval(\n      ctx.guard(() => {\n        for (const player of world.getAllPlayers()) {\n          if (!ctx.isEnabled(player)) continue;\n          const slot = player.selectedSlotIndex;\n          const item = player.getComponent(\"minecraft:inventory\")?.container?.getItem(slot);\n          const durability = item?.getComponent(\"minecraft:durability\");\n          if (!durability || durability.unbreakable || durability.damage === 0) {\n            warned.delete(player.id);\n            continue;\n          }\n\n          const left = durability.maxDurability - durability.damage;\n          const low = (left / durability.maxDurability) * 100 <= ctx.get(player, \"percent\");\n          const key = `${item.typeId}:${slot}`;\n          if (!low) {\n            warned.delete(player.id);\n          } else if (warned.get(player.id) !== key) {\n            warned.set(player.id, key);\n            ctx.feedback(player, `§cYour tool is about to break (${left} uses left)`, {\n              sound: \"note.bass\",\n              pitch: 0.8,\n              volume: 1,\n            });\n          }\n        }\n      }),\n      CHECK_TICKS,\n    );\n\n    world.afterEvents.playerLeave.subscribe((ev) => warned.delete(ev.playerId));\n  },\n};\n","scripts/modules/tree-felling/index.js":"// Sneak + break a log with an axe: fells the whole trunk, paying real\n// durability. Leaves are left to decay the vanilla way. Optionally replants a\n// matching sapling at the base, taken from the player's inventory.\n// See docs/MODULES.md#tree-felling.\nimport { world, GameMode } from \"@minecraft/server\";\nimport { bulkBreak } from \"../../lib/bulk-break.js\";\n\n// Stems that aren't tree trunks (crops), so \"_log\"/\"_stem\" alone isn't enough.\nconst NOT_TRUNKS = new Set([\n  \"minecraft:melon_stem\",\n  \"minecraft:attached_melon_stem\",\n  \"minecraft:pumpkin_stem\",\n  \"minecraft:attached_pumpkin_stem\",\n  \"minecraft:mushroom_stem\",\n]);\n\n// Trunk type -> what replants it.\nconst SAPLINGS = {\n  \"minecraft:oak_log\": \"minecraft:oak_sapling\",\n  \"minecraft:spruce_log\": \"minecraft:spruce_sapling\",\n  \"minecraft:birch_log\": \"minecraft:birch_sapling\",\n  \"minecraft:jungle_log\": \"minecraft:jungle_sapling\",\n  \"minecraft:acacia_log\": \"minecraft:acacia_sapling\",\n  \"minecraft:dark_oak_log\": \"minecraft:dark_oak_sapling\",\n  \"minecraft:pale_oak_log\": \"minecraft:pale_oak_sapling\",\n  \"minecraft:cherry_log\": \"minecraft:cherry_sapling\",\n  \"minecraft:mangrove_log\": \"minecraft:mangrove_propagule\",\n  \"minecraft:crimson_stem\": \"minecraft:crimson_fungus\",\n  \"minecraft:warped_stem\": \"minecraft:warped_fungus\",\n};\n\nconst SOIL = new Set([\n  \"minecraft:grass_block\",\n  \"minecraft:dirt\",\n  \"minecraft:coarse_dirt\",\n  \"minecraft:podzol\",\n  \"minecraft:rooted_dirt\",\n  \"minecraft:moss_block\",\n  \"minecraft:mud\",\n  \"minecraft:muddy_mangrove_roots\",\n  \"minecraft:mycelium\",\n  \"minecraft:crimson_nylium\",\n  \"minecraft:warped_nylium\",\n  \"minecraft:soul_soil\",\n]);\n\nconst MAX_DROP = 32; // how far below the chopped log to look for the ground\n\n/**\n * Plants one matching sapling where the trunk stood: straight down from the\n * chopped log through the (now air) trunk to the first soil block. Uses a\n * sapling from the player's inventory; none means no replant.\n * @returns {boolean} planted\n */\nfunction replantSapling(player, dimension, originLoc, saplingId) {\n  let ground;\n  for (let dy = 1; dy <= MAX_DROP; dy++) {\n    const below = dimension.getBlock({ x: originLoc.x, y: originLoc.y - dy, z: originLoc.z });\n    if (!below) return false;\n    if (below.isAir) continue;\n    if (!SOIL.has(below.typeId)) return false;\n    ground = below;\n    break;\n  }\n  const spot = ground?.above();\n  if (!spot?.isAir) return false;\n\n  const creative = player.getGameMode() === GameMode.Creative;\n  if (!creative) {\n    const container = player.getComponent(\"minecraft:inventory\")?.container;\n    if (!container) return false;\n    let slot = -1;\n    for (let i = 0; i < container.size; i++) {\n      if (container.getItem(i)?.typeId === saplingId) {\n        slot = i;\n        break;\n      }\n    }\n    if (slot < 0) return false;\n    const stack = container.getItem(slot);\n    if (stack.amount > 1) {\n      stack.amount -= 1;\n      container.setItem(slot, stack);\n    } else {\n      container.setItem(slot, undefined);\n    }\n  }\n  spot.setType(saplingId);\n  return true;\n}\n\nfunction isTrunk(typeId) {\n  return (typeId.endsWith(\"_log\") || typeId.endsWith(\"_stem\")) && !NOT_TRUNKS.has(typeId);\n}\n\nexport default {\n  id: \"tree-felling\",\n  name: \"Tree felling\",\n\n  settings: [\n    { key: \"requireSneak\", type: \"toggle\", label: \"Require sneak\", default: true },\n    { key: \"cap\", type: \"slider\", label: \"Max blocks\", default: 128, min: 16, max: 128, step: 16 },\n    { key: \"replant\", type: \"toggle\", label: \"Replant a sapling from your inventory\", default: true },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      if (!ctx.isEnabled(ev.player)) return;\n      const tool = ev.itemStackBeforeBreak;\n      if (!tool || !tool.typeId.endsWith(\"_axe\")) return;\n      const originTypeId = ev.brokenBlockPermutation.type.id;\n      if (!isTrunk(originTypeId)) return;\n      if (ctx.get(ev.player, \"requireSneak\") && !ev.player.isSneaking) return;\n\n      const cap = ctx.get(ev.player, \"cap\");\n      const replant = ctx.get(ev.player, \"replant\");\n\n      ctx.run(() => {\n        const origin = ev.dimension.getBlock(ev.block.location);\n        if (!origin) return;\n        const { broken } = bulkBreak({\n          player: ev.player,\n          origin,\n          originKey: originTypeId,\n          key: (id) => id,\n          cap,\n          protectTool: true, // not exposed as a setting: tree-felling never breaks the tool\n        });\n        // Stripped logs fell too, but map back to the plain log for the sapling.\n        const saplingId = SAPLINGS[originTypeId.replace(\"stripped_\", \"\")];\n        const planted = replant && saplingId && replantSapling(ev.player, ev.dimension, ev.block.location, saplingId);\n        if (broken > 0 || planted) {\n          ctx.feedback(ev.player, `Felled ${broken + 1} logs${planted ? \", sapling planted\" : \"\"}`);\n        }\n      });\n    });\n  },\n};\n","scripts/modules/veinminer/index.js":"// Sneak + break an ore with a pickaxe: flood-fills the vein, paying real\n// durability. See docs/MODULES.md#veinminer.\nimport { world } from \"@minecraft/server\";\nimport { bulkBreak } from \"../../lib/bulk-break.js\";\n\n// coal 0–2, diamond/emerald 3–7, lapis/quartz 2–5, redstone 1–5, nether gold 0–1.\n// copper/iron/gold/ancient debris are left out: no XP in vanilla.\nconst ORE_XP = [\n  { test: (id) => id === \"minecraft:coal_ore\", range: [0, 2] },\n  { test: (id) => id === \"minecraft:diamond_ore\" || id === \"minecraft:emerald_ore\", range: [3, 7] },\n  { test: (id) => id === \"minecraft:lapis_ore\" || id === \"minecraft:quartz_ore\", range: [2, 5] },\n  { test: (id) => id === \"minecraft:redstone_ore\", range: [1, 5] },\n  { test: (id) => id === \"minecraft:nether_gold_ore\", range: [0, 1] },\n];\n\n// Deepslate/lit variants are the same ore for flood-fill purposes.\nfunction oreKey(typeId) {\n  return typeId.replace(/^minecraft:(lit_)?(deepslate_)?/, \"minecraft:\");\n}\n\n// Only these trigger veinminer (after oreKey normalizes deepslate/lit\n// variants away). Plain stone/deepslate must never flood-fill.\nconst ORE_BLOCK_IDS = new Set([\n  \"minecraft:coal_ore\",\n  \"minecraft:iron_ore\",\n  \"minecraft:copper_ore\",\n  \"minecraft:gold_ore\",\n  \"minecraft:redstone_ore\",\n  \"minecraft:lapis_ore\",\n  \"minecraft:diamond_ore\",\n  \"minecraft:emerald_ore\",\n  \"minecraft:quartz_ore\",\n  \"minecraft:nether_gold_ore\",\n  \"minecraft:ancient_debris\",\n]);\n\nfunction xpFor(block, hasSilkTouch) {\n  if (hasSilkTouch) return 0;\n  const entry = ORE_XP.find((e) => e.test(oreKey(block.permutation.type.id)));\n  if (!entry) return 0;\n  const [min, max] = entry.range;\n  return min + Math.floor(Math.random() * (max - min + 1));\n}\n\nexport default {\n  id: \"veinminer\",\n  name: \"Veinminer\",\n\n  settings: [\n    { key: \"requireSneak\", type: \"toggle\", label: \"Require sneak\", default: true },\n    { key: \"cap\", type: \"slider\", label: \"Max blocks\", default: 64, min: 8, max: 64, step: 8 },\n    { key: \"protectTool\", type: \"toggle\", label: \"Never break tool\", default: true },\n  ],\n\n  register(ctx) {\n    world.afterEvents.playerBreakBlock.subscribe((ev) => {\n      if (!ctx.isEnabled(ev.player)) return;\n      const tool = ev.itemStackBeforeBreak;\n      if (!tool || !tool.typeId.endsWith(\"_pickaxe\")) return;\n      if (ctx.get(ev.player, \"requireSneak\") && !ev.player.isSneaking) return;\n\n      const originTypeId = ev.brokenBlockPermutation.type.id;\n      const originKey = oreKey(originTypeId);\n      if (!ORE_BLOCK_IDS.has(originKey)) return;\n      const hasSilkTouch = !!tool.getComponent(\"minecraft:enchantable\")?.getEnchantment(\"silk_touch\");\n      const cap = ctx.get(ev.player, \"cap\");\n      const protectTool = ctx.get(ev.player, \"protectTool\");\n\n      ctx.run(() => {\n        const origin = ev.dimension.getBlock(ev.block.location);\n        if (!origin) return;\n        const { broken } = bulkBreak({\n          player: ev.player,\n          origin,\n          originKey,\n          key: oreKey,\n          cap,\n          protectTool,\n          xp: (block) => xpFor(block, hasSilkTouch),\n        });\n        if (broken > 0) ctx.feedback(ev.player, `Mined ${broken + 1} blocks`);\n      });\n    });\n  },\n};\n"}};
(() => {
// Pure build logic shared by the website and tools/gen-index.mjs: generate
// modules/index.js for a chosen module set, rewrite the manifest version, and
// zip the result. No DOM or Node APIs, so it runs in both.

const identOf = (id) => id.replace(/-(\w)/g, (_, c) => c.toUpperCase());

/** @param {Array<{id: string, name: string, default: boolean}>} included modules in modules.json order */
function generateIndex(included) {
  const meta = Object.fromEntries(included.map((m) => [m.id, { name: m.name, default: m.default }]));
  return `// GENERATED by tools/gen-index.mjs from modules.json. Do not edit by hand.
${included.map((m) => `import ${identOf(m.id)} from "./${m.id}/index.js";`).join("\n")}

export const moduleMeta = ${JSON.stringify(meta, null, 2)};

export default [${included.map((m) => identOf(m.id)).join(", ")}];
`;
}

/**
 * @param {{ manifest: string, modules: Array<any>, files: Record<string, string> }} pack
 * @param {string[]} selectedIds
 * @param {[number, number, number]} version
 * @returns {Array<{ path: string, data: string }>} files relative to the pack root
 */
function buildPackFiles(pack, selectedIds, version) {
  const chosen = new Set(selectedIds);
  const included = pack.modules.filter((m) => chosen.has(m.id) && m.hasCode);

  const manifest = JSON.parse(pack.manifest);
  manifest.header.version = version;
  for (const mod of manifest.modules) mod.version = version;

  const out = [{ path: "manifest.json", data: JSON.stringify(manifest, null, 2) + "\n" }];
  for (const [path, data] of Object.entries(pack.files)) {
    if (path === "scripts/modules/index.js") continue;
    const moduleId = path.match(/^scripts\/modules\/([^/]+)\//)?.[1];
    if (moduleId && !chosen.has(moduleId)) continue;
    out.push({ path, data });
  }
  out.push({ path: "scripts/modules/index.js", data: generateIndex(included) });
  return out;
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(bytes) {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

/** Store-only zip (no compression: the pack is tiny). Fixed timestamp so builds are reproducible. */
function makeZip(entries) {
  const enc = new TextEncoder();
  const DOS_DATE = ((2026 - 1980) << 9) | (1 << 5) | 1;
  const parts = [];
  const central = [];
  let offset = 0;

  for (const { path, data } of entries) {
    const name = enc.encode(path);
    const bytes = typeof data === "string" ? enc.encode(data) : data;
    const crc = crc32(bytes);

    const local = new DataView(new ArrayBuffer(30));
    local.setUint32(0, 0x04034b50, true);
    local.setUint16(4, 20, true);
    local.setUint16(6, 0x0800, true); // UTF-8 names
    local.setUint16(8, 0, true); // store
    local.setUint16(10, 0, true);
    local.setUint16(12, DOS_DATE, true);
    local.setUint32(14, crc, true);
    local.setUint32(18, bytes.length, true);
    local.setUint32(22, bytes.length, true);
    local.setUint16(26, name.length, true);
    parts.push(new Uint8Array(local.buffer), name, bytes);

    const cd = new DataView(new ArrayBuffer(46));
    cd.setUint32(0, 0x02014b50, true);
    cd.setUint16(4, 20, true);
    cd.setUint16(6, 20, true);
    cd.setUint16(8, 0x0800, true);
    cd.setUint16(10, 0, true);
    cd.setUint16(12, 0, true);
    cd.setUint16(14, DOS_DATE, true);
    cd.setUint32(16, crc, true);
    cd.setUint32(20, bytes.length, true);
    cd.setUint32(24, bytes.length, true);
    cd.setUint16(28, name.length, true);
    cd.setUint32(42, offset, true);
    central.push(new Uint8Array(cd.buffer), name);

    offset += 30 + name.length + bytes.length;
  }

  const centralSize = central.reduce((n, p) => n + p.length, 0);
  const end = new DataView(new ArrayBuffer(22));
  end.setUint32(0, 0x06054b50, true);
  end.setUint16(8, entries.length, true);
  end.setUint16(10, entries.length, true);
  end.setUint32(12, centralSize, true);
  end.setUint32(16, offset, true);

  const all = [...parts, ...central, new Uint8Array(end.buffer)];
  const zip = new Uint8Array(all.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of all) {
    zip.set(p, at);
    at += p.length;
  }
  return zip;
}

/** `.mcaddon`: a zip holding the behavior pack folder. */
function buildAddon(pack, selectedIds, version, folder = "QoL_BP") {
  const files = buildPackFiles(pack, selectedIds, version);
  return makeZip(files.map((f) => ({ path: `${folder}/${f.path}`, data: f.data })));
}



window.QOL_BUILDER = { buildAddon, buildPackFiles, generateIndex, makeZip, crc32 };
})();
